# Recount more carefully - my earlier component finding might have issues
demo_in = G['Demo pair 1 input']
h, w = len(demo_in), len(demo_in[0])

def count_color_cells(grid, color):
    count = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == color:
                count += 1
    return count

print("Exact counts per color:")
for color in range(10):
    cnt = count_color_cells(demo_in, color)
    print(f"Color {color}: {cnt} cells")

# Find actual largest connected component for each color
visited = [[False]*w for _ in range(h)]

def bfs_component(grid, start_r, start_c):
    comp = []
    q = [(start_r, start_c)]
    visited[start_r][start_c] = True
    while q:
        r, c = q.pop(0)
        comp.append((r,c))
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == grid[r][c]:
                visited[nr][nc] = True
                q.append((nr, nc))
    return comp

max_comp = (0, [], None)  # (size, component_cells, color)
for r in range(h):
    for c in range(w):
        if visited[r][c]:
            continue
        color = demo_in[r][c]
        comp = bfs_component(demo_in, r, c)
        if len(comp) > max_comp[0]:
            max_comp = (len(comp), comp, color)

print(f"\nLargest component: size={max_comp[0]}, color={max_comp[2]}")

