# Double-check color 5 distribution in test input
test_input = G['Test input']
h, w = len(test_input), len(test_input[0])

def count_color(grid, color):
    return sum(1 for r in range(h) for c in range(w) if grid[r][c] == color)

print("Total cells per color:")
for c in range(10):
    print(f"Color {c}: {count_color(test_input, c)} cells")

# Find all components of color 5 specifically
visited = [[False]*w for _ in range(h)]
comp_num = 0
comp_colors = {}

for r in range(h):
    for c in range(w):
        if visited[r][c]:
            continue
        if test_input[r][c] != 5:
            continue

        comp = []
        q = [(r, c)]
        visited[r][c] = True

        while q:
            curr_r, curr_c = q.pop(0)
            comp.append((curr_r, curr_c))
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and test_input[nr][nc] == 5:
                    visited[nr][nc] = True
                    q.append((nr, nc))

        comp_colors[comp_num] = (len(comp), comp)
        comp_num += 1

print(f"\nColor 5 has {comp_num} components:")
for i, (size, _) in enumerate(sorted(comp_colors.items(), key=lambda x: -x[1][0])):
    rows = set(r for r,c in comp_colors[i][1])
    cols = set(c for r,c in comp_colors[i][1])
    print(f"  Component {i}: {size} cells, bounding box {min(rows)}-{max(rows)+1} x {min(cols)}-{max(cols)+1}")
